using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.PurchaseInvoices.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.PurchaseInvoices.Queries.GetPurchaseInvoiceById;public sealed class GetPurchaseInvoiceByIdQueryHandler(IPurchaseInvoiceRepository repository):IRequestHandler<GetPurchaseInvoiceByIdQuery,Result<PurchaseInvoiceDto>>{public async Task<Result<PurchaseInvoiceDto>>Handle(GetPurchaseInvoiceByIdQuery request,CancellationToken cancellationToken){var e=await repository.FindByIdAsync(request.Id,cancellationToken);return e is null?Result.Failure<PurchaseInvoiceDto>(PurchaseInvoiceErrors.NotFound):Result.Success(PurchaseInvoiceDto.FromEntity(e));}}
